-- Customers in Mexico D.F. | mysql
-- Generated by scripts/export-demo-sql.ts; display formatting only.
-- Ordered sample parameters: ["mexico d.f."]
-- r1 filter: merged; Compatible row-level input block
-- r0 aggregate: merged; Compatible row-level input block
select
  cast(count(*) as char) as `customer_count`
from
  `customers`
where
  (
    cast(lower(`customers`.`city`) as binary) = cast(lower(cast(? as char)) as binary)
  );
